1	import { hashState } from "../hash.js";
2	import {
3	  requireId,
4	  requireInteger,
5	  type ClaimEndReport,
6	  type MatchConfig,
7	  type MatchEnd,
8	  type MatchEvent,
9	  type MatchInput,
10	  type MatchPhase,
11	  type MatchPlayer,
12	  type MatchPlayerResult,
13	  type MatchPlayerStats,
14	  type MatchReport,
15	  type MatchResults,
16	  type MatchState,
17	  type MatchStatEvent,
18	  type MatchStepResult,
19	} from "./state.js";
20	
21	/** Lowest id by UTF-16 code units, independent of locale. */
22	function compareIds(a: string, b: string): number {
23	  return a < b ? -1 : a > b ? 1 : 0;
24	}
25	
26	/** Player control has started and the match has not ended: the only phases that count accomplishments or end reports. */
27	function inPlay(phase: MatchPhase): boolean {
28	  return phase === "departure" || phase === "exploration";
29	}
30	
31	/** Refuses a malformed report; a well-formed one about an unknown player is checked where it is applied. */
32	function checkReport(report: MatchReport, tick: number): void {
33	  switch (report.kind) {
34	    case "join":
35	    case "leave":
36	    case "start":
37	    case "collected":
38	    case "stole":
39	    case "lost":
40	    case "cache-claimed":
41	      requireId(report.playerId, `${report.kind} playerId`);
42	      return;
43	    case "island-visited":
44	      requireId(report.playerId, "island-visited playerId");
45	      requireId(report.island, "island-visited island");
46	      return;
47	    case "gold":
48	      requireId(report.playerId, "gold playerId");
49	      requireInteger(report.gold, "gold");
50	      if (report.gold < 0) throw new RangeError(`gold must not be negative, got ${report.gold}`);
51	      return;
52	    case "duel-ended": {
53	      const [a, b] = report.playerIds;
54	      requireId(a, "duel-ended player");
55	      requireId(b, "duel-ended player");
56	      if (a === b) throw new RangeError(`a duel cannot pit ${a} against themselves`);
57	      if (report.winner !== null && report.winner !== a && report.winner !== b) throw new RangeError(`duel winner ${String(report.winner)} did not fight`);
58	      return;
59	    }
60	    case "match-ended":
61	      if (report.tick !== tick) throw new RangeError(`the claim's match-ended is for tick ${report.tick}, reported on tick ${tick}`);
62	      if (report.reason === "claim") requireId(report.winner, "claim winner");
63	      else if (report.reason === "deadline") {
64	        if (report.winner !== null) throw new RangeError("a deadline has no winner");
65	      } else throw new RangeError(`unknown claim end reason ${String((report as { reason: unknown }).reason)}`);
66	      return;
67	    case "fault":
68	      return;
69	    default:
70	      throw new RangeError(`unknown report kind ${String((report as { kind: unknown }).kind)}`);
71	  }
72	}
73	
74	type MutableStats = { -readonly [K in keyof MatchPlayerStats]: MatchPlayerStats[K] };
75	type WorkingPlayer = { id: string; order: number; left: boolean; stats: MutableStats };
76	
77	function heldRubbings(stats: MatchPlayerStats): number {
78	  return Math.max(0, stats.collected + stats.thefts + stats.cachesClaimed - stats.lost);
79	}
80	
81	/** The results screen: every player who reached control start, the winner first, then by rubbings held, then by id. */
82	export function buildResults(end: MatchEnd, custom: boolean, controlStartTick: number | null, players: readonly MatchPlayer[]): MatchResults {
83	  const lines: MatchPlayerResult[] = players.map((player) => ({
84	    id: player.id,
85	    winner: player.id === end.winner,
86	    left: player.left,
87	    rubbingsHeld: heldRubbings(player.stats),
88	    collected: player.stats.collected,
89	    thefts: player.stats.thefts,
90	    lost: player.stats.lost,
91	    duelsWon: player.stats.duelsWon,
92	    duelsLost: player.stats.duelsLost,
93	    duelsDrawn: player.stats.duelsDrawn,
94	    gold: player.stats.gold,
95	    cachesClaimed: player.stats.cachesClaimed,
96	    islandsVisited: player.stats.islands.length,
97	  }));
98	  lines.sort((a, b) => Number(b.winner) - Number(a.winner) || b.rubbingsHeld - a.rubbingsHeld || compareIds(a.id, b.id));
99	  return {
100	    reason: end.reason,
101	    winner: end.winner,
102	    tick: end.tick,
103	    custom,
104	    elapsedTicks: controlStartTick === null ? 0 : Math.max(0, end.tick - controlStartTick),
105	    players: lines,
106	  };
107	}
108	
109	/**
110	 * Up to one world tick of §2's match flow, in a fixed order: (1) the timed transitions due by `tick` (the ready check
111	 * ends in control start and `departure`; `departure` becomes `exploration`), each on its own scheduled tick, (2) the
112	 * reports in order (joins, leaves, start requests, accomplishments, end reports), (3) the end, if any: a claim, then
113	 * the deadline, then a fault (`aborted`), then no player left after the lobby (`abandoned`), and (4) with no end, the
114	 * lobby and ready rules (a full public lobby or the private host's request starts the ready check; too few players in
115	 * it return to the lobby). A stale or repeated tick, or any input once the match has ended, returns the same state and
116	 * no events. The input state is never mutated.
117	 */
118	export function stepMatch(config: MatchConfig, state: MatchState, input: MatchInput): MatchStepResult {
119	  if (state.end !== null) return { state, events: [] };
120	  requireInteger(input.tick, "tick");
121	  if (input.tick <= state.tick) return { state, events: [] };
122	  const tick = input.tick;
123	  for (const report of input.reports) checkReport(report, tick);
124	
125	  const events: MatchEvent[] = [];
126	  let phase = state.phase;
127	  let readyTick = state.readyTick;
128	  let controlStartTick = state.controlStartTick;
129	  let host = state.host;
130	  let nextOrder = state.nextOrder;
131	  const players = new Map<string, WorkingPlayer>(
132	    state.players.map((player) => [player.id, { id: player.id, order: player.order, left: player.left, stats: { ...player.stats } }]),
133	  );
134	  const present = () => [...players.values()].filter((player) => !player.left);
135	  const moveTo = (to: MatchPhase, at: number) => {
136	    events.push({ kind: "phase-changed", tick: at, from: phase, to });
137	    phase = to;
138	  };
139	  const passHost = () => {
140	    if (!config.custom || (host !== null && players.get(host)?.left === false)) return;
141	    const next = present().sort((a, b) => a.order - b.order)[0]?.id ?? null;
142	    if (next !== host) {
143	      host = next;
144	      events.push({ kind: "host-changed", tick, playerId: host });
145	    }
146	  };
147	
148	  // 1. Time first: a transition due on this tick happens before this tick's reports.
149	  if (phase === "ready" && readyTick !== null && readyTick + config.readyTicks <= tick) {
150	    controlStartTick = readyTick + config.readyTicks;
151	    readyTick = null;
152	    moveTo("departure", controlStartTick);
153	    events.push({ kind: "control-started", tick: controlStartTick });
154	  }
155	  if (phase === "departure" && controlStartTick !== null && controlStartTick + config.departureTicks <= tick) {
156	    moveTo("exploration", controlStartTick + config.departureTicks);
157	  }
158	
159	  // 2. The reports, in order.
160	  const starters: string[] = [];
161	  let claimEnd: ClaimEndReport | null = null;
162	  let fault = false;
163	  const known = (id: string): WorkingPlayer => {
164	    const player = players.get(id);
165	    if (player === undefined) throw new RangeError(`unknown player ${id}`);
166	    return player;
167	  };
168	  const count = (event: MatchStatEvent) => {
169	    if (!inPlay(phase)) return;
170	    switch (event.kind) {
171	      case "collected":
172	        known(event.playerId).stats.collected++;
173	        return;
174	      case "stole":
175	        known(event.playerId).stats.thefts++;
176	        return;
177	      case "lost":
178	        known(event.playerId).stats.lost++;
179	        return;
180	      case "cache-claimed":
181	        known(event.playerId).stats.cachesClaimed++;
182	        return;
183	      case "gold":
184	        known(event.playerId).stats.gold = event.gold;
185	        return;
186	      case "island-visited": {
187	        const stats = known(event.playerId).stats;
188	        if (!stats.islands.includes(event.island)) stats.islands = [...stats.islands, event.island].sort(compareIds);
189	        return;
190	      }
191	      case "duel-ended": {
192	        const fighters = event.playerIds.map(known);
193	        for (const fighter of fighters) {
194	          if (event.winner === null) fighter.stats.duelsDrawn++;
195	          else if (event.winner === fighter.id) fighter.stats.duelsWon++;
196	          else fighter.stats.duelsLost++;
197	        }
198	        return;
199	      }
200	    }
201	  };
202	  for (const report of input.reports) {
203	    switch (report.kind) {
204	      case "join": {
205	        const existing = players.get(report.playerId);
206	        if (existing !== undefined && !existing.left) break;
207	        if (phase !== "lobby") {
208	          events.push({ kind: "join-refused", tick, playerId: report.playerId, reason: "started" });
209	        } else if (present().length >= config.seats) {
210	          events.push({ kind: "join-refused", tick, playerId: report.playerId, reason: "full" });
211	        } else {
212	          players.set(report.playerId, {
213	            id: report.playerId,
214	            order: nextOrder++,
215	            left: false,
216	            stats: { collected: 0, thefts: 0, lost: 0, duelsWon: 0, duelsLost: 0, duelsDrawn: 0, gold: config.startingGold, cachesClaimed: 0, islands: [] },
217	          });
218	          events.push({ kind: "player-joined", tick, playerId: report.playerId });
219	          passHost();
220	        }
221	        break;
222	      }
223	      case "leave": {
224	        const player = players.get(report.playerId);
225	        if (player === undefined || player.left) break;
226	        // Before control start the player never raced: they leave no line in the results.
227	        if (controlStartTick === null) players.delete(player.id);
228	        else player.left = true;
229	        events.push({ kind: "player-left", tick, playerId: player.id });
230	        passHost();
231	        break;
232	      }
233	      case "start":
234	        starters.push(report.playerId);
235	        break;
236	      case "match-ended":
237	        // Only a running match can end by the claim rules; the claim wins over a deadline reported on the same tick.
238	        if (!inPlay(phase)) break;
239	        if (report.winner !== null) known(report.winner);
240	        if (claimEnd === null || (claimEnd.reason === "deadline" && report.reason === "claim")) claimEnd = report;
241	        break;
242	      case "fault":
243	        fault = true;
244	        break;
245	      default:
246	        count(report);
247	    }
248	  }
249	
250	  // 3. The first end wins, and within a tick: a claim, the deadline, a fault, then an empty room.
251	  let end: MatchEnd | null = null;
252	  if (claimEnd !== null) end = { reason: claimEnd.reason, winner: claimEnd.winner, tick };
253	  else if (fault) end = { reason: "aborted", winner: null, tick };
254	  else if (phase !== "lobby" && present().length === 0) end = { reason: "abandoned", winner: null, tick };
255	
256	  if (end === null) {
257	    // 4. The lobby and the ready check.
258	    if (phase === "lobby") {
259	      for (const playerId of starters) {
260	        if (phase !== "lobby") break;
261	        if (!config.custom) events.push({ kind: "start-refused", tick, playerId, reason: "public" });
262	        else if (playerId !== host) events.push({ kind: "start-refused", tick, playerId, reason: "not-host" });
263	        else if (present().length < config.minPlayers) events.push({ kind: "start-refused", tick, playerId, reason: "too-few" });
264	        else {
265	          readyTick = tick;
266	          moveTo("ready", tick);
267	        }
268	      }
269	      if (phase === "lobby" && !config.custom && present().length >= config.seats) {
270	        readyTick = tick;
271	        moveTo("ready", tick);
272	      }
273	    } else if (phase === "ready" && present().length < config.minPlayers) {
274	      readyTick = null;
275	      moveTo("lobby", tick);
276	    }
277	  }
278	
279	  const sorted: MatchPlayer[] = [...players.values()]
280	    .sort((a, b) => compareIds(a.id, b.id))
281	    .map((player) => ({ id: player.id, order: player.order, left: player.left, stats: player.stats }));
282	  let results: MatchResults | null = null;
283	  if (end !== null) {
284	    moveTo("ended", tick);
285	    results = buildResults(end, config.custom, controlStartTick, sorted);
286	    events.push({ kind: "match-ended", tick, reason: end.reason, winner: end.winner, results });
287	    readyTick = null;
288	  }
289	
290	  return {
291	    state: {
292	      tick,
293	      phase,
294	      custom: state.custom,
295	      durationTicks: state.durationTicks,
296	      players: sorted,
297	      nextOrder,
298	      host,
299	      readyTick,
300	      controlStartTick,
301	      end,
302	      results,
303	    },
304	    events,
305	  };
306	}
307	
308	/** Match time since control start, frozen at the end; 0 before control start and never negative. */
309	export function elapsed(state: MatchState, tick: number): number {
310	  requireInteger(tick, "tick");
311	  if (state.controlStartTick === null) return 0;
312	  const until = state.end === null ? tick : Math.min(tick, state.end.tick);
313	  return Math.max(0, until - state.controlStartTick);
314	}
315	
316	/** Match time left before the deadline: the full duration before control start, never negative. */
317	export function remaining(state: MatchState, tick: number): number {
318	  return Math.max(0, state.durationTicks - elapsed(state, tick));
319	}
320	
321	export interface MatchReplay {
322	  readonly state: MatchState;
323	  readonly events: readonly MatchEvent[];
324	  readonly hash: string;
325	}
326	
327	/** Steps a sequence of inputs from a state, collecting every event; `hash` is the final state's `hashState`. */
328	export function replayMatch(config: MatchConfig, state: MatchState, inputs: readonly MatchInput[]): MatchReplay {
329	  let current = state;
330	  const events: MatchEvent[] = [];
331	  for (const input of inputs) {
332	    const stepped = stepMatch(config, current, input);
333	    current = stepped.state;
334	    events.push(...stepped.events);
335	  }
336	  return { state: current, events, hash: hashState(current) };
337	}
