2	import type {
3	  ClaimChannel,
4	  ClaimConfig,
5	  ClaimEncounter,
6	  ClaimEvent,
7	  ClaimInterruptReason,
8	  ClaimPlayer,
9	  ClaimResult,
10	  ClaimState,
11	  ClaimStepResult,
12	  ClaimTickInput,
13	} from "./state.js";
14	
15	/** Squared distance from the claim point, refusing coordinates whose square would not be an exact integer. */
16	export function claimDistanceSquared(config: ClaimConfig, x: number, y: number): number {
17	  const dx = x - config.claimPoint.x;
18	  const dy = y - config.claimPoint.y;
19	  const squared = dx * dx + dy * dy;
20	  if (!Number.isSafeInteger(squared)) throw new RangeError(`position (${x}, ${y}) is too far from the claim point`);
21	  return squared;
22	}
23	
24	export function insideTreasureCircle(config: ClaimConfig, x: number, y: number): boolean {
25	  return claimDistanceSquared(config, x, y) <= config.circleRadius * config.circleRadius;
26	}
27	
28	/**
29	 * Whether a player meets §5's conditions to start claiming on this tick, protection aside: starting ends protection
30	 * (§6), so a protected player may start. A player can wait with interact held; this does not say a channel is free.
31	 */
