140	/**
141	 * A match's timings and test-only settings. Production uses `DEFAULT_MATCH_TUNING`; tests shorten the timings through
142	 * `startGameServer({ matchTuning })` (never read by the production entry), and assert in world ticks.
143	 */
144	export interface MatchTuning {
145	  /** The ledger's rules (§4, §11, §12): collection and claim holds, the theft window, the seat reservation, gold. */
146	  readonly objectives: ObjectiveRules;
147	  /** The encounter rules (§6): windups, the countdown and ready check, protections, the respawn delay. */
148	  readonly encounters: EncounterRules;
149	  /** §12: world ticks a fighter may be away from an unfinished duel before forfeiting it (10 s). */
150	  readonly duelAbsenceTicks: number;
151	  /** Colyseus' reconnection window, the outer bound (70 s). */
152	  readonly reconnectionSeconds: number;
153	  /** Test-only: deal the sources in this layout (types per island) instead of the private shuffle. */
154	  readonly sourceLayout: readonly (readonly string[])[] | undefined;
155	  /**
156	   * The room's randomness: the world, ledger and duel seeds. Production uses `cryptoRandom`; tests inject their own to
157	   * show the ledger's deal follows it (and never the public match code).
158	   */
159	  readonly random: RandomSource;
160	  /** Check `checkLedger` and the room's own invariant after every world tick (development and tests). */
161	  readonly checkInvariants: boolean;
162	}
163	
164	export const DEFAULT_MATCH_TUNING: MatchTuning = {
165	  objectives: objectiveRules,
166	  encounters: encounterRules,
167	  duelAbsenceTicks: DUEL_RECONNECT_SECONDS * WORLD_TICKS_PER_SECOND,
168	  reconnectionSeconds: RECONNECTION_OUTER_BOUND_SECONDS,
169	  sourceLayout: undefined,
170	  random: cryptoRandom,
171	  checkInvariants: true,
172	};
173	
174	/** A duel at sea: the encounter rules' duel, its synced lobby and marker, and the duel machine the fighters play. */
175	interface SeaDuel {
176	  /** The encounter rules' duel id, also the ledger's. */
177	  readonly id: string;
178	  /** The opaque key of its lobby and marker in the synced state. */
179	  readonly key: string;
180	  /** Attacker (slot 0), then the grappled player (slot 1). */
181	  readonly players: readonly [string, string];
182	  readonly lobby: SeaDuelSchema;
183	  readonly machine: DuelMachine;
184	  /** The rules' ready check ended it (a forfeit or a cancellation), so no end report goes back to them. */
185	  endedByRules: boolean;
186	  /** The fight's end went to the rules (or they decided it themselves). */
187	  ended: boolean;
188	  /** The ledger's settlement went to the rules. */
189	  settled: boolean;
190	  /** The world tick after which the lobby leaves the fighters' views, once settled. */
191	  removeAfterTick: number | undefined;
192	}
193	
194	/** A player whose connection dropped (§12): their seat's outer bound, and since when they are away from a duel. */
195	interface Away {
196	  readonly reconnection: Deferred<Client> | undefined;
197	  /** The world tick they dropped out of an unfinished duel; undefined outside one. */
198	  duelAbsentSince: number | undefined;
199	}
200	
201	/** What a player last saw of their own holds and duels, for their HUD. */
202	interface Notices {
203	  channelResult: string;
204	  channelResultAt: number;
205	  settledRole: string;
206	  stolen: string;
207	  goldChange: number;
208	  settledAt: number;
209	  settledChoice: string;
210	  choiceDeadline: number;
211	}
212	
213	/** What tests and diagnostics read about a duel at sea. */
214	export interface SeaDuelDiagnostics extends DuelDiagnostics {
215	  readonly id: string;
216	  readonly outcome: DuelOutcome | undefined;
217	  readonly players: readonly [string, string];
218	  readonly seed: number;
219	  readonly inputLog: ReturnType<DuelAuthority["inputLog"]>;
220	}
221	
222	/** Checks a create or join request for a match before matchmaking places it (see `authorizePrivateEntry`). */
223	export async function authorizeEntry(options: unknown): Promise<true> {
224	  return authorizePrivateEntry(options, MATCH_ADMISSION);
225	}
226	
227	/** A match's admission: the `match` listing, the match option schemas and the match refusal messages. */
228	const MATCH_ADMISSION: AdmissionRules = {
229	  roomName: MATCH_ROOM,
230	  createSchema: createMatchOptionsSchema,
231	  joinSchema: joinMatchOptionsSchema,
232	  noSuchMessage: NO_SUCH_MATCH_MESSAGE,
233	  codeRequiredMessage: MATCH_CODE_REQUIRED_MESSAGE,
234	  fullMessage: matchFullMessage,
235	};
236	
237	const sameTarget = (channel: LedgerChannel | null, target: InteractTarget): boolean =>
238	  channel !== null &&
239	  (target.kind === "collect"
240	    ? channel.kind === "collect" && channel.sourceId === target.sourceId
241	    : channel.kind === "claim" && channel.cacheId === target.cacheId && channel.rubbingId === target.rubbingId);
242	
243	/**
244	 * One private match (§14): the only writer of its state. It runs the shared simulation on a 60 Hz fixed step,
245	 * applies validated client intent, and mirrors the simulation into the synced schema after every world step.
246	 *
247	 * Encounters (§6): each world step the room builds the tick's snapshot for `stepEncounters` (every ship, whether its
248	 * player is connected, pressed the grapple, or has a loaded arena) and applies the events: a landed grapple stops both
249	 * ships and opens a duel at sea, a `DuelMachine` (the standalone duel room's own) whose fight starts when the rules
250	 * say so; its end goes back as a report; the returns and respawns move ships. Reserved and respawning ships get
251	 * neutral input.
252	 *
253	 * Rubbings (§4, §11, §12): the objective ledger is the only writer of rubbings and gold; the room calls its operations
254	 * and never moves either itself. Holding E moored at an island's dock collects its first eligible source, or else
255	 * claims a rubbing from a recovery cache at that dock. A reservation reserves the duel in the ledger; the fight's end
256	 * is reported to it; the room reports `settled` to the encounter rules only when the ledger has settled the duel (the
257	 * winner's theft choice, or the default at the deadline), and only then do the players return. The world tick drives
258	 * every §12 timer: a drop disconnects the player in the ledger at once (the ship stays, and can be grappled), a
259	 * fighter away from an unfinished duel forfeits it after `duelAbsenceTicks`, the seat expires at the ledger's
260	 * deadline into a cache at the respawn dock, and any other leave is a quit into a cache at the nearest dock by sea.
261	 * No path removes a ship while the ledger still counts its player; `checkInvariants` checks that and `checkLedger`
262	 * after every tick.
263	 *
264	 * Visibility (§16): every client has a Colyseus StateView. After each mirror the room puts into it the client's own
265	 * ship and every ship inside that ship's sight radius, and takes out the rest, so a ship out of sight is never encoded
266	 * into that client's patches. Ships in a duel or waiting to respawn are hidden from everyone else (a duel shows as a
267	 * marker). Grapples, markers and caches are filtered by the same sight rule (a grapple's target is blanked for a
268	 * viewer who cannot see it); a player's status (gold, rubbings, what their island and dock hold, their theft choice)
269	 * and duel go to that player only, and a duel's frames and probes are messages to its two fighters. A fighter or a
270	 * player waiting to respawn sees no other ship. Terrain is static content every client already has, so it is not
271	 * synced at all.
272	 */
273	export class MatchRoom extends Room<{ state: MatchStateSchema; metadata: MatchMetadata }> {
274	  override maxClients = privateMatch.maxPlayers;
275	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in InputGate. */
276	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
277	  override patchRate = PATCH_INTERVAL_MS;
278	  override state = new MatchStateSchema();
279	
280	  private readonly config = defaultSimulationConfig;
281	  private tuning: MatchTuning = DEFAULT_MATCH_TUNING;
282	  private encounterConfig: EncounterConfig = createEncounterConfig({ map: defaultSimulationConfig.map });
283	  private simulation: MatchState = createMatchState(0);
284	  private encounters: EncounterState = createEncounterState(this.encounterConfig);
285	  private ledger: LedgerState = createMatchLedger({ map: defaultSimulationConfig.map, seed: 0, rules: objectiveRules });
286	  private readonly gates = new Map<string, InputGate>();
287	  /** Duels at sea by encounter id, from the grapple until their lobby leaves the fighters' views. */
288	  private readonly seaDuels = new Map<string, SeaDuel>();
289	  private nextDuelKey = 1;
290	  /** Players whose connection dropped and who have not come back or left. */
291	  private readonly away = new Map<string, Away>();
292	  /** Players who started a collection or cache claim this tick: their protection ends on the next (§6). */
293	  private protectionEndedNext = new Set<string>();
294	  private readonly notices = new Map<string, Notices>();
295	  /** Ledger duels whose settlement is already in the players' notices. */
296	  private readonly noticed = new Set<string>();
297	  /** Theft choices per session in the current second, for the rate cap. */
298	  private readonly choiceRate = new Map<string, { windowStart: number; count: number }>();
299	  /** Reports the rules refused (none are expected), for tests. */
300	  private refusedReports = 0;
301	  /** Ledger requests the room made that the ledger refused, by operation and reason, for tests. */
302	  private readonly refusals: string[] = [];
303	  /** Invariant violations found after a world tick (none are expected), for tests. */
304	  private readonly violations: string[] = [];
305	  /** The creator's one-time token; cleared once the creator's seat is taken. */
306	  private createToken: string | undefined;
307	
308	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
309	    return authorizeEntry(options);
310	  }
311	
312	  /** The match's timings; the server's test-only setting overrides it in a subclass (`startGameServer`). */
313	  protected matchTuning(): MatchTuning {
314	    return DEFAULT_MATCH_TUNING;
315	  }
316	
317	  override async onCreate(options: unknown): Promise<void> {
318	    // Only a token-carrying request creates a match. A join by code reaches here only when its match filled up or
319	    // closed after authorizeEntry admitted it (joinOrCreate then falls back to create).
320	    const parsed = createMatchOptionsSchema.safeParse(options);
321	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, MATCH_UNAVAILABLE_MESSAGE);
322	    this.createToken = parsed.data.createToken;
323	    const code = await this.allocateCode();
324	    this.tuning = this.matchTuning();
325	    this.encounterConfig = createEncounterConfig({ map: this.config.map, rules: this.tuning.encounters });
326	    this.encounters = createEncounterState(this.encounterConfig);
327	    this.simulation = createMatchState(this.tuning.random(0, 2 ** 32));
328	    // The ledger's seed is the room's own private randomness, never the public match code (§3, §16).
329	    this.ledger = createMatchLedger({ map: this.config.map, seed: this.tuning.random(0, 2 ** 32), rules: this.tuning.objectives, layout: this.tuning.sourceLayout });
330	    this.state.code = code;
331	    this.state.protocolVersion = PROTOCOL_VERSION;
332	    this.state.custom = privateMatch.custom;
333	    // Colyseus copied the filterBy fields of the create request, the token among them, into the listing's metadata.
334	    // Replacing the metadata drops the token before the listing is first stored.
335	    await this.setMatchmaking({ metadata: { code, custom: privateMatch.custom } });
336	
337	    this.onMessage(MessageType.Input, (client, message: unknown) => {
338	      this.gates.get(client.sessionId)?.receive(message, this.simulation.frame);
339	    });
340	    // A duel's messages reach only its machine, and only from its two fighters.
341	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveInput(client.sessionId, message));
342	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.duelOfSession(client.sessionId)?.machine.receiveProbeReply(client.sessionId, message));
343	    this.onMessage(DuelMessageType.Ready, (client, message: unknown) => {
344	      if (duelReadyMessageSchema.safeParse(message).success) this.duelOfSession(client.sessionId)?.machine.markReady(client.sessionId);
345	    });
346	    this.onMessage(RubbingMessageType.ChooseTheft, (client, message: unknown) => this.receiveTheftChoice(client.sessionId, message));
347	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
348	    this.onMessage("*", () => undefined);
349	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
350	  }
351	
352	  /**
353	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
354	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
355	   */
356	  override onJoin(client: Client, options: unknown): void {
357	    this.admit(options);
358	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
359	    this.ledgerStep("addPlayer", addPlayer(this.ledger, { playerId: client.sessionId, tick: this.simulation.worldTick }));
360	    this.gates.set(client.sessionId, new InputGate());
361	    client.view = new StateView();
362	    this.mirror();
363	  }
364	
365	  /**
366	   * A player's connection dropped without leaving (§12). The ledger marks them disconnected at once (their hold is
367	   * cancelled and their seat reserved until its deadline); the ship stays in the world and can be grappled. A fighter
368	   * in an unfinished duel is marked away, the fight going on with their input substituted, and forfeits if still away
369	   * after `duelAbsenceTicks`. Colyseus keeps the socket's seat for the outer bound only.
370	   */
371	  override onDrop(client: Client): void {
372	    const id = client.sessionId;
373	    // A request refused in onJoin (a wrong code, a used token) still drops and leaves, but never became a player.
374	    if (findPlayer(this.ledger, id) === undefined) return;
375	    const tick = this.simulation.worldTick;
376	    this.ledgerStep("disconnectPlayer", disconnectPlayer(this.ledger, { playerId: id, tick }));
377	    const duel = this.duelOfSession(id);
378	    const fighting = duel !== undefined && duel.machine.outcome === undefined;
379	    if (fighting) duel.machine.drop(id);
380	    const reconnection = this.allowReconnection(client, this.tuning.reconnectionSeconds);
381	    reconnection.catch(() => undefined);
382	    this.away.set(id, { reconnection, duelAbsentSince: fighting ? tick : undefined });
383	  }
384	
385	  /** The same player is back before the deadline: the same identity, view, ship and rubbings; a fighter resumes. */
386	  override onReconnect(client: Client): void {
387	    const id = client.sessionId;
388	    this.away.delete(id);
389	    this.ledgerStep("reconnectPlayer", reconnectPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick }));
390	    this.duelOfSession(id)?.machine.reconnect(id);
391	  }
392	
393	  /**
394	   * A player is gone for good. Unless the reservation already expired (the world tick removed them), this is a quit:
395	   * a consented leave, or Colyseus' outer bound closing first. The ledger forfeits a duel in progress and sends the
396	   * rest of their rubbings into a cache at the dock nearest their ship by sea; then the ship leaves.
397	   */
398	  override onLeave(client: Client): void {
399	    const id = client.sessionId;
400	    const player = findPlayer(this.ledger, id);
401	    if (player !== undefined && player.status !== "left") this.quit(id);
402	    this.removePlayer(id);
403	    client.view?.dispose();
404	    client.view = undefined;
405	    this.mirror();
406	  }
407	
408	  /**
409	   * Test-only (the server's test-placement setting, off by default): puts a player's ship at rest on a navigable tile.
410	   * Visibility follows at once, as after any move.
411	   */
412	  placeShip(sessionId: string, placement: Placement): void {
413	    this.simulation = placeShip(this.config, this.simulation, sessionId, placement);
414	    this.mirror();
415	  }
416	
417	  /** The ship ids a client's view holds, for tests and diagnostics. */
418	  viewedShipIds(sessionId: string): string[] {
419	    const view = this.clients.get(sessionId)?.view;
420	    if (view === undefined) return [];
421	    return [...this.state.ships.values()].filter((ship) => view.has(ship)).map((ship) => ship.id);
422	  }
423	
424	  /** Inputs dropped per client and reason, for tests and diagnostics. */
425	  droppedInputs(sessionId: string): InputGate["dropped"] | undefined {
426	    return this.gates.get(sessionId)?.dropped;
427	  }
428	
429	  /** The encounter rules' state, for tests. */
430	  get encounterState(): EncounterState {
431	    return this.encounters;
432	  }
433	
434	  /** The simulation state, for tests. */
435	  get matchState(): MatchState {
436	    return this.simulation;
437	  }
438	
439	  /** The objective ledger, for tests. */
440	  get ledgerState(): LedgerState {
441	    return this.ledger;
442	  }
443	
444	  /** The match's timings, for tests. */
445	  get timings(): MatchTuning {
446	    return this.tuning;
447	  }
448	
449	  /** Reports the encounter rules refused, for tests (none are expected). */
450	  get refusedDuelReports(): number {
451	    return this.refusedReports;
452	  }
453	
454	  /** Ledger requests the room made and the ledger refused, as "operation: reason", for tests. */
455	  get ledgerRefusals(): readonly string[] {
456	    return this.refusals;
457	  }
458	
459	  /** Invariant violations found after any world tick so far (none are expected), for tests. */
460	  get invariantViolations(): readonly string[] {
461	    return this.violations;
462	  }
463	
464	  /** The duel at sea a player is in (until its lobby leaves their view), for tests and the harness. */
465	  seaDuelDiagnostics(sessionId: string): SeaDuelDiagnostics | undefined {
466	    const duel = this.duelOfSession(sessionId);
467	    if (duel === undefined) return undefined;
468	    return { ...duel.machine.diagnostics(), id: duel.id, outcome: duel.machine.outcome, players: duel.players, seed: duel.lobby.seed, inputLog: duel.machine.authority.inputLog() };
469	  }
470	
471	  private admit(options: unknown): void {
472	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, MATCH_ADMISSION);
473	  }
474	
475	  /** Applies a ledger step, and remembers a refusal (the room checks before it asks, so none are expected). */
476	  private ledgerStep<R extends { readonly ok: boolean; readonly rejection: string | null }>(operation: string, stepped: { state: LedgerState; result: R }): R {
477	    this.ledger = stepped.state;
478	    if (!stepped.result.ok) this.refusals.push(`${operation}: ${stepped.result.rejection}`);
479	    return stepped.result;
480	  }
481	
482	  private advance(): void {
483	    const frame = this.simulation.frame + 1;
484	    const inputs: Record<string, PlayerInput> = {};
485	    const held = this.heldPlayers();
486	    for (const [sessionId, gate] of this.gates) {
487	      // A reserved or respawning ship ignores its player's helm (§6).
488	      if (held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
489	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
490	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
491	    }
492	    this.simulation = step(this.config, this.simulation, inputs);
493	    for (const duel of this.seaDuels.values()) duel.machine.advance();
494	    if (!isWorldStep(this.simulation.frame)) return;
495	    const tick = this.simulation.worldTick;
496	    // The ledger's clock first: choice windows that closed settle with the default theft.
497	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
498	    this.runAbsences(tick);
499	    this.stepEncounters(frame, held);
500	    this.stepChannels(frame, tick);
501	    for (const gate of this.gates.values()) gate.worldStepTaken();
502	    this.noteSettlements();
503	    this.checkInvariants(tick);
504	    this.mirror();
505	  }
506	
507	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
508	  private heldPlayers(): Set<string> {
509	    const held = new Set<string>();
510	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
511	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
512	    return held;
513	  }
514	
515	  /** The duel at sea a session fights in (until its lobby is removed). */
516	  private duelOfSession(sessionId: string): SeaDuel | undefined {
517	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
518	    return undefined;
519	  }
520	
521	  /** Takes a settled duel's lobby out of its fighters' views. */
522	  private closeSeaDuel(duel: SeaDuel): void {
523	    this.state.duels.delete(duel.key);
524	    this.seaDuels.delete(duel.id);
525	  }
526	
527	  /**
528	   * §12 on the world tick: a fighter away from an unfinished duel for `duelAbsenceTicks` forfeits it (the duel goes on
529	   * to its settlement; they keep their seat); a disconnected player whose reservation deadline has come is removed,
530	   * their remaining rubbings going into a cache at the respawn dock the encounter rules would choose.
531	   */
532	  private runAbsences(tick: number): void {
533	    for (const [id, away] of this.away) {
534	      if (away.duelAbsentSince === undefined) continue;
535	      const duel = this.duelOfSession(id);
536	      if (duel === undefined || duel.machine.outcome !== undefined) away.duelAbsentSince = undefined;
537	      else if (tick - away.duelAbsentSince >= this.tuning.duelAbsenceTicks) {
538	        duel.machine.leave(id);
539	        away.duelAbsentSince = undefined;
540	      }
541	    }
542	    for (const player of this.ledger.players) {
543	      if (player.status !== "disconnected" || player.reservationDeadline === null || tick < player.reservationDeadline) continue;
544	      const position = this.respawnDockOf(player.id);
545	      this.ledgerStep("expireReservation", expireReservation(this.ledger, { playerId: player.id, tick, position }));
546	      const duel = this.duelOfSession(player.id);
547	      if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(player.id);
548	      const away = this.away.get(player.id);
549	      this.removePlayer(player.id);
550	      // The socket's seat goes too: Colyseus then calls onLeave, which finds the player already gone.
551	      if (typeof away?.reconnection?.reject === "function") away.reconnection.reject(false);
552	    }
553	  }
554	
555	  /** §12 expiry: the dock the encounter rules would respawn this player at, from where their ship is (or waits). */
556	  private respawnDockOf(id: string): { x: number; y: number } {
557	    const ship = this.simulation.ships.find((each) => each.id === id);
558	    const respawn = this.encounters.players.find((each) => each.id === id)?.respawn ?? null;
559	    const from = respawn !== null ? { x: respawn.x, y: respawn.y } : ship !== undefined ? { x: ship.x, y: ship.y } : dockCentre(this.config.map, 0);
560	    const waiting = new Set(this.encounters.players.filter((each) => each.respawn !== null).map((each) => each.id));
561	    const opponents = this.simulation.ships.filter((each) => each.id !== id && !waiting.has(each.id)).map((each) => ({ x: each.x, y: each.y }));
562	    const point = this.encounterConfig.modes.ship.rules.respawnPoint({ encounter: from, own: from, opponents, clearRadius: this.encounterConfig.respawnClearRadius });
563	    return { x: point.x, y: point.y };
564	  }
565	
566	  /** §12 quit: a duel in progress is forfeited (in the ledger and in the fight), the rest goes to the nearest dock. */
567	  private quit(id: string): void {
568	    const ship = this.simulation.ships.find((each) => each.id === id);
569	    const at = ship ?? dockCentre(this.config.map, 0);
570	    const position = dockCentre(this.config.map, nearestDockBySea(this.config.map, at.x, at.y));
571	    this.ledgerStep("quitPlayer", quitPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick, position }));
572	    const duel = this.duelOfSession(id);
573	    if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(id);
574	  }
575	
576	  /** The ship and the input channel of a player who has left the ledger's match. */
577	  private removePlayer(id: string): void {
578	    this.simulation = removeShip(this.simulation, id);
579	    this.gates.delete(id);
580	    this.away.delete(id);
581	    this.choiceRate.delete(id);
582	  }
583	
584	  /**
585	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
586	   * the last tick and of duels the ledger has settled, then the events applied. The rules alone choose targets, land
587	   * or miss grapples, start fights and decide returns; the room moves ships and runs the duels.
588	   */
589	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
590	    const tick = this.simulation.worldTick;
591	    const endedBy = this.protectionEndedNext;
592	    this.protectionEndedNext = new Set();
593	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
594	      const gate = this.gates.get(ship.id);
595	      const duel = this.duelOfSession(ship.id);
596	      return {
597	        id: ship.id,
598	        mode: "ship",
599	        x: ship.x,
600	        y: ship.y,
601	        heading: ship.heading,
602	        connected: this.clients.get(ship.id) !== undefined,
603	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
604	        ready: duel?.machine.isReady(ship.id) === true,
605	        // §6: last tick's collection or cache claim ended this player's protection.
606	        protectionEndedBy: endedBy.has(ship.id) ? "collection" : null,
607	      };
608	    });
609	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });

