tests/e2e/duel.spec.ts:109:test("a practice duel: a jab, then a throw pressed J then K with rollover, drop the dummy's health [scenario:duel-practice]", async ({ page }, testInfo) => {
tests/e2e/duel.spec.ts:188:test("two browsers duel online: a strike lands, and both show the same health, clock and result [scenario:duel-online]", async ({ browser }, testInfo) => {
tests/e2e/duel.spec.ts:191:  const hostContext = await browser.newContext();
tests/e2e/duel.spec.ts:192:  const guestContext = await browser.newContext();
tests/e2e/duel.spec.ts:194:    const host = await hostContext.newPage();
tests/e2e/duel.spec.ts:195:    const guest = await guestContext.newPage();
tests/e2e/theftLoop.spec.ts:4:import { attachScreenshot, createMatch, joinMatch, place, readout, selfId, TILE } from "./helpers.js";
tests/e2e/theftLoop.spec.ts:75:test("two browsers each collect a rubbing at their own island, the host grapples the guest, wins by tapping attack keys and steals the guest's type within five seconds [scenario:theft-loop]", async ({ browser, request }, testInfo) => {
